/* APLUS P6 English Prelim — Engine V9
   Uses Paper 2 Generation Layer V1 + Quality Gate V2.
   Keeps the existing V8 engine untouched.
*/
(function(){'use strict';
const G=window.APLUS_P6_PSLE_PAPER2_GENERATION_V1,KEY='APLUS_P6_PRELIM_SESSION_V9',DONE='APLUS_P6_PRELIM_COMPLETED_V9',TOTAL=6600;
let state={version:'9.0',started:false,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:'',className:'',profile:'standard',paperId:'',seed:0,startedAt:0,submittedAt:0};let timer=null;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s??'').toLowerCase().replace(/[“”‘’".,!?;:()[\]{}]/g,' ').replace(/\s+/g,' ').trim();
function show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id)?.classList.add('active')}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}
function load(){try{let x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&x.version==='9.0'&&Array.isArray(x.questions)&&x.questions.length===75){state=Object.assign(state,x);return true}}catch(e){}return false}
function fmt(s){s=Math.max(0,Number(s)||0);return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function startClock(){clearInterval(timer);timer=setInterval(()=>{if(!state.started||state.submitted)return;state.remaining--;if(state.remaining<=0){state.remaining=0;save();renderTimer();submit(true);return}renderTimer();if(state.remaining%10===0)save()},1000);renderTimer()}
function renderTimer(){if($('timer'))$('timer').textContent=fmt(state.remaining)}
function buildNav(){let nav=$('sectionNav');if(!nav)return;nav.innerHTML=G.blueprint.map(b=>{let qs=state.questions.filter(q=>q.section===b.id);if(!qs.length)return '';return '<div class="nav-section"><b>'+esc(b.name)+'</b><div class="nav-questions">'+qs.map(q=>'<button class="nav-q '+(q.number===state.index+1?'current ':'')+(state.answers[q.id]!=null&&state.answers[q.id]!==''?'answered':'')+'" data-q="'+q.number+'">'+q.number+'</button>').join('')+'</div></div>'}).join('');nav.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{state.index=Number(b.dataset.q)-1;save();renderQuestion()})}
function current(){return state.questions[state.index]}
function answerValue(q){return state.answers[q.id]??''}
function renderQuestion(){let q=current();if(!q)return;let b=G.blueprint.find(x=>x.id===q.section),card=$('questionCard');if(!b)return;$('bookletLabel').textContent='BOOKLET '+b.b;$('sectionLabel').textContent=b.name.replace('BOOKLET '+b.b+' · ','').toUpperCase();$('progressText').textContent='Question '+q.number+' of 75';$('markText').textContent=q.marks+' '+(q.marks===1?'mark':'marks');$('progressBar').style.width=(q.number/75*100)+'%';let html='';if(q.visual)html+='<div class="visual-box"><h3>'+esc(q.visual.title)+'</h3><pre>'+esc(q.visual.text)+'</pre></div>';if(q.passage)html+='<div class="passage-box">'+esc(q.passage).replace(/\n/g,'<br>')+'</div>';html+='<div class="question-number">Question '+q.number+'</div><h2 class="question-stem">'+esc(q.question)+'</h2>';if(q.type==='mcq')html+='<div class="options">'+q.options.map((o,i)=>'<label class="option"><input type="radio" name="answer" value="'+esc(o)+'" '+(norm(answerValue(q))===norm(o)?'checked':'')+'><span>'+String.fromCharCode(65+i)+'. '+esc(o)+'</span></label>').join('')+'</div>';else html+='<textarea id="oeAnswer" class="oe-answer" rows="4" placeholder="Type your answer here">'+esc(answerValue(q))+'</textarea>';card.innerHTML=html;if(q.type==='mcq')card.querySelectorAll('input').forEach(x=>x.onchange=()=>{state.answers[q.id]=x.value;save();buildNav()});else $('oeAnswer').oninput=e=>{state.answers[q.id]=e.target.value;save();buildNav()};buildNav();$('prevBtn').disabled=state.index===0;$('nextBtn').textContent=state.index===74?'REVIEW & SUBMIT':'Next';window.scrollTo({top:0,behavior:'smooth'})}
function summary(){let answered=state.questions.filter(q=>state.answers[q.id]!=null&&String(state.answers[q.id]).trim()!=='').length;return '<strong>'+answered+' / 75</strong> questions answered<br><span>'+ (75-answered)+' unanswered</span>'}
function scoreAnswer(q,a){if(a==null||String(a).trim()==='')return 0;let accepted=q.acceptedPatterns||[q.answer];let n=norm(a);if(accepted.some(x=>norm(x)===n))return q.marks;let toks=n.split(' ').filter(Boolean);if(q.section==='comprehension'&&toks.length>=2){let key=norm(q.answer).split(' ').filter(x=>x.length>3);let hit=key.filter(x=>toks.includes(x)).length;return hit>=Math.max(1,Math.ceil(key.length*.6))?q.marks:0}if(q.section==='synthesis'&&toks.length>=2){let key=norm(q.answer).split(' ').filter(x=>x.length>2);let hit=key.filter(x=>toks.includes(x)).length;return hit>=Math.max(1,Math.ceil(key.length*.75))?q.marks:0}return 0}
function result(){let total=0;const sec={};const skills={};state.questions.forEach(q=>{let s=scoreAnswer(q,state.answers[q.id]);total+=s;sec[q.section]=(sec[q.section]||0)+s;let k=q.skill||q.section;skills[k]??={score:0,max:0};skills[k].score+=s;skills[k].max+=q.marks});$('score').textContent=total+' / 90';$('percentage').textContent=Math.round(total/90*100)+'%';$('paperId').textContent='Paper ID: '+esc(state.paperId);$('resultMessage').innerHTML=total>=81?'Excellent accuracy':total>=63?'Strong progress':total>=45?'More practice needed':'Let’s rebuild the basics';$('sectionResults').innerHTML=G.blueprint.map(b=>{let s=sec[b.id]||0;return '<div class="result-row"><span>'+esc(b.name)+'</span><strong>'+s+' / '+b.marks+'</strong></div>'}).join('');let arr=Object.entries(skills).sort((a,b)=>b[1].score/b[1].max-a[1].score/a[1].max).slice(0,12);$('skillResults').innerHTML='<h3>Skill Profile</h3>'+arr.map(([k,v])=>'<div class="result-row"><span>'+esc(k)+'</span><strong>'+v.score+' / '+v.max+'</strong></div>').join('');show('result')}
function submit(auto){if(state.submitted)return;if(!auto&&!confirm('Submit this paper? Your answers will be locked for this attempt.'))return;state.submitted=true;state.submittedAt=Date.now();clearInterval(timer);try{localStorage.setItem(DONE,JSON.stringify(state));localStorage.removeItem(KEY)}catch(e){}result()}
function generationError(res){let reason=res&&res.diagnostics&&res.diagnostics.reason?res.diagnostics.reason:(res&&res.error)||'unknown error';let extra=res&&res.diagnostics&&res.diagnostics.section?(' · '+res.diagnostics.section):'';alert('The paper could not be generated safely.\n\nReason: '+reason+extra+'\n\nThe generator has stopped rather than showing an incomplete paper. Please try Generate New Paper 2 again.');}
function generate(){if(!G||typeof G.generate!=='function'){alert('Paper 2 generation layer is not available.');return}let profile=$('paperProfile').value||'standard',candidate=$('candidateName').value.trim(),className=$('candidateClass').value.trim(),seed=Math.floor(Math.random()*4294967295),res=G.generate({profile,seed});if(!res||!res.ok||!Array.isArray(res.paper)||res.paper.length!==75){generationError(res);return}state={version:'9.0',started:true,submitted:false,index:0,remaining:TOTAL,questions:res.paper,answers:{},candidate,className,profile,paperId:'APLUS-P6-ENG-P2-'+new Date().getFullYear()+'-'+String((res.seed||seed)%1000000).padStart(6,'0'),seed:res.seed||seed,startedAt:Date.now(),submittedAt:0};save();show('exam');startClock();renderQuestion()}
function resume(){if(!load())return;show(state.submitted?'result':'exam');if(state.submitted)result();else{startClock();renderQuestion()}}
function review(){state.submitted=false;show('exam');renderQuestion()}
function printPaper(){let w=window.open('','_blank');if(!w)return;let rows=state.questions.map(q=>'<section style="page-break-inside:avoid;margin:0 0 24px"><h3>Question '+q.number+' · '+esc(q.sectionName||q.section)+'</h3>'+(q.visual?'<pre>'+esc(q.visual.text)+'</pre>':'')+(q.passage?'<div>'+esc(q.passage).replace(/\n/g,'<br>')+'</div>':'')+'<p><b>'+esc(q.question)+'</b></p>'+(q.options?'<ol type="A">'+q.options.map(o=>'<li>'+esc(o)+'</li>').join('')+'</ol>':'')+'<p><b>Student answer:</b> '+esc(state.answers[q.id]||'')+'</p></section>').join('');w.document.write('<!doctype html><html><head><title>APLUS P6 English Prelim</title><style>body{font-family:Arial;max-width:850px;margin:30px auto;line-height:1.5}pre{white-space:pre-wrap;border:1px solid #ccc;padding:12px}</style></head><body><h1>APLUS P6 English Prelim</h1><p>PSLE-Style English Language Examination · Paper 2</p><p>Candidate: '+esc(state.candidate)+' · Class: '+esc(state.className)+'</p><p>Paper ID: '+esc(state.paperId)+'</p>'+rows+'</body></html>');w.document.close();w.focus();w.print()}
$('startBtn').onclick=generate;$('resumeBtn').onclick=resume;$('prevBtn').onclick=()=>{if(state.index>0){state.index--;save();renderQuestion()}};$('nextBtn').onclick=()=>{if(state.index<74){state.index++;save();renderQuestion()}else{show('submitScreen');$('submitSummary').innerHTML=summary()}};$('confirmSubmitBtn').onclick=()=>submit(false);$('backToExamBtn').onclick=()=>{show('exam');renderQuestion()};$('reviewBtn').onclick=review;$('printBtn').onclick=printPaper;$('newExamBtn').onclick=()=>{try{localStorage.removeItem(DONE);localStorage.removeItem(KEY)}catch(e){}show('landing')};
try{let x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&x.version==='9.0'&&Array.isArray(x.questions)&&x.questions.length===75)$('resumeBtn').classList.remove('hidden')}catch(e){}
window.APLUS_P6_PRELIM_V9={generate,submit,printPaper};
})();
